(()=>{const poll=()=>document.querySelectorAll('[hx-trigger*="every"]').forEach(e=>{const m=e.getAttribute('hx-trigger').match(/every\s+(\d+)s/);if(!m||e.dataset.polling)return;e.dataset.polling='1';setInterval(()=>fetch(e.getAttribute('hx-get')).then(r=>r.text()).then(t=>e.innerHTML=t).catch(()=>{}),Number(m[1])*1000)});poll()})();
